const lines = FILE_CONTENT.split('\n').map(l => l.replace(/\s+/g,' ').trim()).filter(l => l && !/^PLOS ONE/.test(l));
const txt = lines.join(' ');
const heads = ['Results','Discussion','Limitations','Conclusion','Practical','Methods','Materials and methods','References'];
for (const h of heads) { const i = txt.indexOf(' '+h+' '); console.log(h+' at '+i); }
const r = txt.indexOf(' Results '); const d = txt.indexOf(' Discussion '); const ref = txt.indexOf(' References ');
console.log('---RESULTS---'); console.log(txt.slice(r, Math.min(d, r+6000)));
console.log('---DISCUSSION (first 3500)---'); console.log(txt.slice(d, d+3500));
const lim = txt.search(/Limitations?\b/); console.log('---LIMITATIONS---'); if (lim>0) console.log(txt.slice(lim, lim+1200));
console.log('---TAIL---'); console.log(txt.slice(ref-200, ref+300));

