input.command:
cd /Users/kristinarash/Library/Caches/sportsci-batch-99 && python3 -I -c '
import json
tax=json.load(open("taxonomy.json"))
inp={d["id"]:d["sourceFile"] for d in json.load(open("inputs.json"))}
bad=[]
for i in ["Q57","Q58","Q59","Q60","Q61","Q62","Q63","Q64"]:
    s=open(f"drafts/{i}.json",encoding="utf-8").read()
    d=json.loads(s)
    if d["sourceFile"]!=inp[i]: bad.append((i,"sourceFile"))
    if "—" in s: bad.append((i,"emdash"))
    if d["studyDesign"] not in tax["studyDesigns"]: bad.append((i,"design",d["studyDesign"]))
    if d["primaryDomain"] not in tax["domains"] or d["primaryDomain"] not in d["domains"]: bad.append((i,"primary"))
    for k,f in [("domains","domains"),("audiences","audiences"),("sports","sports"),("populations","populations")]:
        for v in d[k]:
            if v not in tax[f]: bad.append((i,k,v))
    p=d["paper"]
    if not p["doi"].startswith("10."): bad.append((i,"doi"))
    if p["citation"].count(",")<1: bad.append((i,"cite"))
print("problems:", bad if bad else "none")
'

